]

# Find all cells of each color (other than 6 which is background)
color_positions = {}
for r in range(len(input_grid)):
    for c in range(len(input_grid[0])):
        val = input_grid[r][c]
        if val != 6:
            if val not in color_positions:
                color_positions[val] = []
            color_positions[val].append((r, c))

for color, positions in sorted(color_positions.items()):
    positions_sorted = sorted(positions)
    print(f"Color {color}: {positions_sorted}")
    print(f"  Count: {len(positions)}")

